META={'id':'g8-ma-hl-c','subj':'數學','name':'八上 數學 翰林 C卷','source':'翰林版 八年級數學（三）C卷（114上，教用版答案與解析；僅收選擇題）'}

sec('第1回 1-1 乘法公式')
ch(r'利用和的平方公式，計算 \(132^2+2\times132\times68+68^2\) 的值為何？',['2000','4000','20000','40000'],4,r'原式＝\((132+68)^2=200^2=40000\)。')
ch(r'利用 \((a+b)(c+d)=ac+ad+bc+bd\)，計算 \(299.5\times100.5\) 的值為下列何者？',['30099.25','30099.75','30199.75','30200.25'],2,r'\(299.5\times100.5=(300-0.5)(100+0.5)=300\times100+300\times0.5-0.5\times100-0.5\times0.5=30000+150-50-0.25=30099.75\)。')
ch(r'【素養】下列哪一個算式的結果與 \(409^2\) 相同？',[r'\(400^2+800\times9+9^2\)',r'\(400^2+400\times9+9\)',r'\(400^2+9^2\)',r'\(400^2+800\times9+9\)'],1,r'\(409^2=(400+9)^2=400^2+2\times400\times9+9^2=400^2+800\times9+9^2\)。')
ch(r'【素養】利用平方差公式，計算 \(1995^2-5^2\) 的值為何？',['380000','3980000','3990000','3998000'],2,r'\(1995^2-5^2=(1995+5)(1995-5)=2000\times1990=3980000\)。')
ch(r'【素養】若 \(199^2=200^2+\square+1\)，則 \(\square\) 的值為何？',['－198','198','－400','400'],3,r'\(199^2=(200-1)^2=200^2-2\times200\times1+1^2=200^2-400+1\)，故 \(\square=-400\)。')
ch(r'【素養】傑克將 298 看成 \(300-2\) 快速算出答案，請依照他的方法，利用分配律完成下列計算：\(298\times250=(300-\underline{a})\times250=\underline{b}\times250-\underline{a}\times250=\underline{c}-500=\underline{d}\)，則下列何者正確？',[r'\(a=-2\)',r'\(b=298\)',r'\(c=7500\)',r'\(d=74500\)'],4,r'\(a=2\)，\(b=300\)，\(c=75000\)，\(d=74500\)。')
ch(r'【素養】下列哪一個整數最接近 \((50.5)^2\)？',['2549','2550','2551','2552'],2,r'\((50.5)^2=(50+0.5)^2=50^2+2\times50\times0.5+(0.5)^2=2500+50+0.25=2550.25\)，故 \((50.5)^2\) 最接近 2550。')
ch(r'【素養】已知 \(\left(199\dfrac{2}{3}\right)^2=(200-a)^2=200^2-400a+b\)，則 \(a+b\) 的值為何？',[r'\(\dfrac{4}{9}\)',r'\(\dfrac{5}{9}\)',r'\(\dfrac{2}{3}\)',r'\(\dfrac{7}{9}\)'],1,r'\(\left(199\dfrac{2}{3}\right)^2=\left(200-\dfrac{1}{3}\right)^2=200^2-400\times\dfrac{1}{3}+\left(\dfrac{1}{3}\right)^2\Rightarrow a=\dfrac{1}{3}\)，\(b=\dfrac{1}{9}\)，\(a+b=\dfrac{1}{3}+\dfrac{1}{9}=\dfrac{4}{9}\)。')
ch('【素養】附圖中圖形面積的變化，整理後可用哪一個式子表示？',[r'\(a^2+2\cdot(a+b)\cdot b-b^2=(a+b)^2\)',r'\(a^2+2\cdot(a+b)\cdot b-b^2=(a-b)^2\)',r'\(a^2-2\cdot(a+b)\cdot b-b^2=(a+b)^2\)',r'\(a^2-2\cdot(a+b)\cdot b-b^2=(a-b)^2\)'],1,r'\(a^2+b\cdot(a+b)-b^2+b\cdot(a+b)=(a+b)^2\Rightarrow a^2+2\cdot(a+b)\cdot b-b^2=(a+b)^2\)。',img=(1,525,948,1000,1052))
ch(r'【素養】利用平方差公式，計算 \((2.02)^2-(1.98)^2\) 的值為何？',['4','1.6','1.4','0.16'],4,r'原式＝\((2.02+1.98)(2.02-1.98)=4\times0.04=0.16\)。')
ch(r'【素養】若 \(80\dfrac{3}{4}\times120\dfrac{1}{4}=A+\dfrac{3}{16}\)，則 \(A\) 的值為何？',['9710','9700','9680','9600'],1,r'\(\left(80+\dfrac{3}{4}\right)\left(120+\dfrac{1}{4}\right)=80\times120+80\times\dfrac{1}{4}+\dfrac{3}{4}\times120+\dfrac{3}{4}\times\dfrac{1}{4}=9600+20+90+\dfrac{3}{16}=9710+\dfrac{3}{16}\)，故 \(A=9710\)。')
ch('【素養】如附圖，有一個腰長為 125 公尺的等腰直角三角形公園，其內部有一個腰長為 25 公尺的等腰直角三角形草地。若此公園扣除草地面積後，則剩下的面積為多少平方公尺？',['6000','6500','7000','7500'],4,r'所求＝\(\dfrac{125^2}{2}-\dfrac{25^2}{2}=\dfrac{1}{2}(125^2-25^2)=\dfrac{1}{2}(125+25)(125-25)=\dfrac{1}{2}\times150\times100=7500\)（平方公尺）。',img=(2,370,58,512,150))
endp()

sec('第2回 1-2 多項式的加減')
ch(r'下列哪一個選項為 \(x\) 的多項式？',[r'\(2x^2+x-5=0\)',r'\(6x^2+|x|-7\)',r'\(5x^2-2x+3\)',r'\(3x^2-\dfrac{4}{x}+5\)'],3,r'(A) 為一元二次方程式；(B)(D) \(x\) 不可在絕對值內或分母，故選(C)。')
ch(r'多項式 \(5-x+x^3-3x^2\) 為 \(x\) 的幾次多項式？',['三次','二次','一次','零次'],1,r'最高次項是 \(x^3\)，所以這個多項式的次數是 3。')
ch(r'下列有關多項式 \(x^2-5x+7\) 的敘述何者正確？',[r'\(x^2\) 項的係數為 0',r'\(x\) 項的係數為 5','常數項為 7','各項係數的和為 13'],3,r'\(x^2\) 項的係數為 1，\(x\) 項的係數為 －5，常數項為 7，各項係數的和為 \(1+(-5)+7=3\)。')
ch('下列各組多項式中，哪一組是同類項？',[r'\(6x\) 與 \(6y\)',r'\(\dfrac{1}{3}x^2\) 與 \(-3x^2\)',r'\(-2y\) 與 \(-y^2\)',r'\(3x\) 與 \(x^3\)'],2,r'\(\dfrac{1}{3}x^2\) 與 \(-3x^2\) 都是 \(x^2\) 的同類項。')
ch(r'【素養】若 \((x^2+5)+(-2x^2+3x-7)=ax^2+bx+c\)，則 \(a+b+c\) 之值為何？',['0','1','3','5'],1,r'\((x^2+5)+(-2x^2+3x-7)=-x^2+3x-2\Rightarrow a=-1\)，\(b=3\)，\(c=-2\)，\(a+b+c=(-1)+3+(-2)=0\)。')
ch(r'【素養】附圖為 \((x^2+6x-5)-(3x^2-2x+4)\) 的直式運算，則運算式中 \(a\)、\(b\) 之值分別為何？',[r'\(a=4\)，\(b=-9\)',r'\(a=8\)，\(b=-9\)',r'\(a=-4\)，\(b=9\)',r'\(a=-8\)，\(b=9\)'],2,r'\(a=6-(-2)=8\)，\(b=-5-4=-9\)。',img=(3,395,1322,512,1392))
ch(r'【素養】下列哪一個多項式中的 \(x\) 項係數最大？',[r'\(x^2-5x+7\)',r'\(5+x\)',r'\(4x^2+3x\)',r'\(x^2-x+2\)'],3,r'(A) －5；(B) 1；(C) 3；(D) －1，故選(C)。')
ch(r'【素養】計算 \((5x^2+4x+1)+(2x^2+4x+3)\) 的結果為下列何者？',[r'\(7x^2+4\)',r'\(10x^2+8x+3\)',r'\(3x^2+8x+4\)',r'\(7x^2+8x+4\)'],4,r'原式＝\((5x^2+2x^2)+(4x+4x)+(1+3)=7x^2+8x+4\)。')
ch(r'【素養】計算 \((5x^2-3x-7)-(-2x^2+3x+7)\) 的結果為下列何者？',[r'\(3x^2\)',r'\(3x^2-6x-14\)',r'\(7x^2-6x-14\)',r'\(7x^2-14\)'],3,r'原式＝\(5x^2-3x-7+2x^2-3x-7=(5x^2+2x^2)+(-3x-3x)+(-7-7)=7x^2-6x-14\)。')
ch(r'【素養】已知有一個多項式與 \(2x^2-7x+5\) 的和為 \(3x^2-5x-3\)，則此多項式為何？',[r'\(x^2-12x+8\)',r'\(x^2+12x+2\)',r'\(x^2-2x-2\)',r'\(x^2+2x-8\)'],4,r'設此多項式為 \(A\)，\(A+(2x^2-7x+5)=3x^2-5x-3\Rightarrow A=(3x^2-5x-3)-(2x^2-7x+5)=x^2+2x-8\)。')
ch(r'【素養】計算 \((5x^3-x+3)-(4-3x^2+7x^3)\) 的結果為下列何者？',[r'\(x^3+2x^2-4\)',r'\(-2x^3+3x^2-x-1\)',r'\(-2x^3-3x^2-x-1\)',r'\(12x^3+3x^2-x-1\)'],2,r'原式＝\(5x^3-x+3-4+3x^2-7x^3=(5x^3-7x^3)+3x^2-x+(3-4)=-2x^3+3x^2-x-1\)。')
ch(r'【素養】計算 \((5x^2-3)-(6x+7)+(-7x+3x^2)\) 的結果為下列何者？',[r'\(8x^2-13x-10\)',r'\(8x^2-x-10\)',r'\(8x^2-13x+4\)',r'\(2x^2-13x-10\)'],1,r'原式＝\(5x^2-3-6x-7-7x+3x^2=(5x^2+3x^2)+(-6x-7x)+(-3-7)=8x^2-13x-10\)。')
endp()

sec('第3回 1-3 多項式的乘除')
ch(r'計算 \((x^2-1)(x+3)\) 的結果為下列何者？',[r'\(x^3+3x^2-x-3\)',r'\(x^3-3x^2-x+3\)',r'\(x^3+3x^2+x-3\)',r'\(x^3+3x^2-x+3\)'],1,r'原式＝\(x^3+3x^2-x-3\)。')
ch('下列多項式乘法的計算結果何者正確？',[r'\((-3x)^2=9x\)',r'\(-2x\cdot(3x+2)=-6x^2+4x\)',r'\((x+5)\cdot(-4x)=-4x^2-20x\)',r'\(6x\cdot(7x-1)=42x^2-1\)'],3,r'(A) \(9x^2\)；(B) \(-6x^2-4x\)；(D) \(42x^2-6x\)，故選(C)。')
ch('利用乘法公式計算下列各式的結果何者正確？',[r'\((x+3)^2=x^2+9\)',r'\((3x-1)^2=9x^2-1\)',r'\((2x+4)(2x-4)=4x^2-16x\)',r'\((1-6x)^2=1-12x+36x^2\)'],4,r'(A) \(x^2+6x+9\)；(B) \(9x^2-6x+1\)；(C) \(4x^2-16\)；(D) 正確。')
ch(r'【素養】計算 \((x^2-8x-2)\div(2x+4)\) 得商式為 \(Q\)，餘式為 \(R\)，則下列何者正確？',[r'\(Q=-2x+5\)，\(R=6\)',r'\(Q=2x-5\)，\(R=18\)',r'\(Q=\dfrac{1}{2}x-5\)，\(R=-22\)',r'\(Q=\dfrac{1}{2}x-5\)，\(R=18\)'],4,r'以長除法計算 \((x^2-8x-2)\div(2x+4)\)，得 \(Q=\dfrac{1}{2}x-5\)，\(R=18\)。')
ch(r'【素養】附圖為 \((2x^2+3x-1)(3x+5)\) 的直式運算，則算式中 \(a\)、\(b\) 的值分別為何？',[r'\(a=1\)、\(b=18\)',r'\(a=1\)、\(b=12\)',r'\(a=19\)、\(b=12\)',r'\(a=19\)、\(b=18\)'],3,r'\(a=10+9=19\)，\(b=15+(-3)=12\)，故選(C)。',img=(5,215,1358,362,1462))
ch('【素養】如附圖，求塗色部分的面積為多少平方單位？',[r'\(6x+14\)',r'\(12x+15\)',r'\(4x^2+10x+9\)',r'\(4x^2+12x+15\)'],2,r'面積＝\((x+4)(2x+3)-(x+1)(2x-3)=(2x^2+11x+12)-(2x^2-x-3)=12x+15\)（平方單位）。',img=(5,835,342,998,438))
ch(r'【素養】計算 \((2x^2-4x-7)\div(-2x)\) 的餘式為下列何者？',['0','－7',r'\(\dfrac{7}{2}\)',r'\(-\dfrac{7}{2}\)'],2,r'以長除法計算得商式為 \(-x+2\)，餘式為 \(-7\)。')
ch(r'【素養】下列有關甲、乙兩題的計算過程何者正確？甲：\(4x\times(\quad)=28x^2\)，\((\quad)=\dfrac{28x^2}{4x}=7x\)；乙：\(4x\times(\quad)=7x^2\)，\((\quad)=\dfrac{7x^2}{4x}=\dfrac{7}{4}x\)',['甲、乙皆正確','甲、乙皆錯誤','甲正確，乙錯誤','甲錯誤，乙正確'],1,r'甲、乙皆正確。')
ch(r'【素養】若多項式 \(6x^2-x-2\) 除以 \(2x+1\) 得商式為 \(ax+b\)，餘式為 \(c\)，則 \(a+b+c\) 之值為何？',['0','1','2','3'],2,r'以長除法計算得商式為 \(3x-2\)，餘式為 0，\(a=3\)，\(b=-2\)，\(c=0\)，故 \(a+b+c=3+(-2)+0=1\)。')
ch(r'【素養】若多項式 \(9x^2-10\) 除以 \(3x-1\) 得商式為 \(Q\)，餘式為 \(R\)，則 \(Q+R=\)？',[r'\(3x-10\)',r'\(3x-9\)',r'\(3x-8\)',r'\(3x+1\)'],3,r'以長除法計算得 \(Q=3x+1\)，\(R=-9\)，故 \(Q+R=(3x+1)+(-9)=3x-8\)。')
ch(r'【素養】已知多項式 \(A\) 除以 \(2x-7\) 得商式為 \(3x+5\)，餘式為 4，求多項式 \(A\) 為下列何者？',[r'\(6x^2-11x-31\)',r'\(6x^2-11x-39\)',r'\(6x^2+11x-31\)',r'\(5x^2+31x+39\)'],1,r'\(A=(2x-7)(3x+5)+4=6x^2+10x-21x-35+4=6x^2-11x-31\)。')
ch(r'【素養】已知 \(B\) 為一個多項式，且 \(3x^2+7x+1=(x+3)\times B+7\)，求多項式 \(B\) 為下列何者？',[r'\(3x-1\)',r'\(3x-2\)',r'\(3x+1\)',r'\(3x+2\)'],2,r'\(B=(3x^2+7x+1-7)\div(x+3)=(3x^2+7x-6)\div(x+3)=3x-2\)。')
endp()

sec('第4回 2-1 平方根的意義')
ch(r'若 \(a>0\)，且 \(a^2=7\)，則 \(a\) 可記為下列何者？',[r'\(\pm\sqrt{7}\)',r'\(\sqrt{7}\)',r'\(-\sqrt{7}\)',r'\(7^2\)'],2,r'若 \(a>0\)，\(a^2=7\)，則 \(a=\sqrt{7}\)。')
ch(r'邊長為 \(\sqrt{5}\) 的正方形，其面積為多少平方單位？',[r'\(\sqrt{5}\)',r'\(\sqrt{10}\)',r'\(\sqrt{20}\)','5'],4,r'正方形面積＝\((\sqrt{5})^2=5\)（平方單位）。')
ch(r'已知 \(a=\sqrt{123}\)，\(b=11\)，\(c=\sqrt{119}\)，則 \(a\)、\(b\)、\(c\) 三數的大小關係為何？',[r'\(a>b>c\)',r'\(b>c>a\)',r'\(c>a>b\)',r'\(c>b>a\)'],1,r'\((\sqrt{123})^2=123\)，\(11^2=121\)，\((\sqrt{119})^2=119\)，因為 \(123>121>119\)，所以 \(\sqrt{123}>11>\sqrt{119}\)，故 \(a>b>c\)。')
ch('請問 3 介於下列哪兩個數之間？',[r'\(\sqrt{2}\)、\(\sqrt{5}\)',r'\(\sqrt{5}\)、\(\sqrt{7}\)',r'\(\sqrt{8}\)、\(\sqrt{11}\)',r'\(\sqrt{10}\)、\(\sqrt{13}\)'],3,r'\(3=\sqrt{9}\)，介於 \(\sqrt{8}\)、\(\sqrt{11}\) 之間。')
ch(r'【素養】\(-\sqrt{2}\) 是下列哪一個數的平方根？',['－4','－2','2','4'],3,r'\((-\sqrt{2})^2=(\sqrt{2})^2=2\)。')
ch('【素養】下列各數的值，何者正確？',[r'\(\sqrt{4.9}=0.7\)',r'\(\sqrt{\dfrac{8}{18}}=\dfrac{2}{3}\)',r'\(-(\sqrt{6})^2=6\)',r'\(\sqrt{(-5)^2}=-5\)'],2,r'(A) \(\sqrt{0.49}=0.7\)；(B) \(\sqrt{\dfrac{8}{18}}=\sqrt{\dfrac{4}{9}}=\sqrt{\left(\dfrac{2}{3}\right)^2}=\dfrac{2}{3}\)；(C) \(-(\sqrt{6})^2=-6\)；(D) \(\sqrt{(-5)^2}=5\)。')
ch(r'【素養】如附圖，\(7-\sqrt{15}\) 在數線上的位置應在哪兩點之間？（\(A\)、\(B\)、\(C\)、\(D\)、\(E\) 分別對應 0、1、2、3、4）',[r'\(A\) 點和 \(B\) 點',r'\(B\) 點和 \(C\) 點',r'\(C\) 點和 \(D\) 點',r'\(D\) 點和 \(E\) 點'],4,r'\(\sqrt{15}\approx3.\cdots\)，\(7-\sqrt{15}\approx7-3.\cdots=3.\cdots\)，故在 \(D\) 點和 \(E\) 點之間。',img=(7,845,338,1000,395))
ch('【素養】下列敘述何者正確？',[r'\(\sqrt{64}=\pm8\)','0.3 是 0.9 的平方根',r'\(\sqrt{(-2)^2}=-2\)','－3 是 9 的平方根'],4,r'(A) \(\sqrt{64}=8\)；(B) 0.3 是 0.09 的平方根；(C) \(\sqrt{(-2)^2}=\sqrt{2^2}=2\)，故選(D)。')
ch(r'【素養】下列 \(\sqrt{31}\)、\(\sqrt{37}\)、\(\sqrt{41}\)、\(\sqrt{43}\)、\(\sqrt{47}\)、\(\sqrt{51}\) 六個數中，介於 6 和 7 之間的數有多少個？',['2','3','4','5'],3,r'\(6=\sqrt{36}\)，\(7=\sqrt{49}\)，有 \(\sqrt{37}\)、\(\sqrt{41}\)、\(\sqrt{43}\)、\(\sqrt{47}\) 介於 6 和 7 之間，共 4 個。')
ch(r'【素養】若 \(-6\) 是 \(5x-4\) 的負平方根，則 \(x\) 的值為何？',['5','6','7','8'],4,r'\(5x-4=(-6)^2\Rightarrow5x-4=36\Rightarrow5x=40\Rightarrow x=8\)。')
ch(r'【素養】已知 \((3.6)^2=12.96\)，\((3.65)^2=13.3225\)，\((3.7)^2=13.69\)，\((3.75)^2=14.0625\)，利用十分逼近法求 \(\sqrt{13}\) 的近似值為何？（以四捨五入法求到小數點後第一位）',['3.5','3.6','3.7','3.8'],2,r'\(3.6<\sqrt{13}<3.65\Rightarrow\sqrt{13}\approx3.6\)。')
ch('【素養】小於 100 的正整數中，平方根為整數的有多少個？',['9','10','50','99'],1,r'\(1^2=1\)、\(2^2=4\)、\(3^2=9\)、\(4^2=16\)、\(5^2=25\)、\(6^2=36\)、\(7^2=49\)、\(8^2=64\)、\(9^2=81\)，所以 1、4、9、16、25、36、49、64、81，共 9 個。')
endp()

sec('第5回 1-1～2-1 複習')
ch('下列有關乘法公式的運算何者正確？',[r'\(43^2+43\times27+27^2=(43+27)^2\)',r'\(43^2-27^2=(43+27)(43-27)\)',r'\(47^2-47\times17+17^2=(47-17)^2\)',r'\((47+53)(53-47)=47^2-53^2\)'],2,r'(A) \(43^2+2\times43\times27+27^2=(43+27)^2\)；(C) \(47^2-2\times47\times17+17^2=(47-17)^2\)；(D) \((47+53)(53-47)=53^2-47^2\)。')
ch(r'若 \(A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，則 \(2A-B\) 為 \(x\) 的幾次多項式？',['零次','一次','二次','三次'],3,r'\(2A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，\(2A-B\) 為 \(x\) 的二次多項式。')
ch('下列利用乘法公式計算的多項式何者正確？',[r'\((x+3)(x-3)=x^2-6x-9\)',r'\((3x+2)^2=9x^2+6x+4\)',r'\((2x-3)^2=4x^2-6x+9\)',r'\((-2x+3)(-2x-3)=4x^2-9\)'],4,r'(A) \(x^2-9\)；(B) \(9x^2+12x+4\)；(C) \(4x^2-12x+9\)；(D) 正確。')
ch(r'若 \(A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，則 \(2A\times B\) 為 \(x\) 的幾次多項式？',['一次','二次','三次','四次'],3,r'\(2A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，則 \(2A\times B\) 為 \(x\) 的三次多項式。')
ch(r'【素養】若 \(a\)、\(b\) 為常數，且 \(ax^2+bx+3\) 為 \(x\) 的一次多項式，則下列敘述何者正確？',[r'\(a\neq0\)，\(b\neq0\)',r'\(a=0\)，\(b\neq0\)',r'\(a\neq0\)，\(b=0\)',r'\(a=0\)，\(b=0\)'],2,r'\(ax^2+bx+3\) 為 \(x\) 的一次多項式，則 \(a=0\)，\(b\neq0\)。')
ch(r'【素養】若 \(a=\dfrac{12}{5}\)，\(b=2.5\)，\(c=\sqrt{6}\)，則 \(a\)、\(b\)、\(c\) 三數的大小關係為何？',[r'\(a>b>c\)',r'\(a>c>b\)',r'\(b>c>a\)',r'\(c>a>b\)'],3,r'\(a=\dfrac{12}{5}=2.4\)，\(a^2=5.76\)；\(b^2=(2.5)^2=6.25\)；\(c^2=(\sqrt{6})^2=6\)。因為 \(b^2>c^2>a^2\)，且 \(a\)、\(b\)、\(c\) 皆為正數，所以 \(b>c>a\)。')
ch(r'【素養】已知 \(A\) 為 \(x\) 的一次多項式，\(B\) 為 \(x\) 的二次多項式，且 \(B\div A\) 的餘式不為 0，則 \(B\div A\) 的餘式次數是幾次？',['零次','一次','二次','不一定'],1,r'\(B\div A\) 的餘式次數小於除式 \(A\) 的一次，且餘式不為 0，故餘式的次數為零次。')
ch(r'【素養】翰翰和小林想要利用公式算出 \(\left(29\dfrac{1}{2}\right)^2\) 的值，兩人的做法如下：翰翰：\(\left(29\dfrac{1}{2}\right)^2=\left(30-\dfrac{1}{2}\right)^2=30^2-30+\left(\dfrac{1}{2}\right)^2\)；小林：\(\left(29\dfrac{1}{2}\right)^2=29^2+\left(\dfrac{1}{2}\right)^2\)。如果翰翰和小林接下來的計算都沒有錯誤，則下列敘述何者正確？',['兩人做法都對','兩人做法都不對','只有翰翰做對','只有小林做對'],3,r'翰翰：\(\left(29\dfrac{1}{2}\right)^2=\left(30-\dfrac{1}{2}\right)^2=30^2-2\times30\times\dfrac{1}{2}+\left(\dfrac{1}{2}\right)^2=30^2-30+\left(\dfrac{1}{2}\right)^2\)；小林：\(\left(29\dfrac{1}{2}\right)^2=\left(29+\dfrac{1}{2}\right)^2=29^2+2\times29\times\dfrac{1}{2}+\left(\dfrac{1}{2}\right)^2=29^2+29+\left(\dfrac{1}{2}\right)^2\)，故選(C)。')
ch(r'【素養】已知 \(A\) 為一個多項式，且 \(A-(3x^2-4x+6)=2x^2+8x-9\)，則多項式 \(A\) 為下列何者？',[r'\(5x^2+6x-3\)',r'\(5x^2+4x-3\)',r'\(x^2-12x+15\)',r'\(-x^2+12x-15\)'],2,r'\(A=(2x^2+8x-9)+(3x^2-4x+6)=(2x^2+3x^2)+(8x-4x)+(-9+6)=5x^2+4x-3\)。')
ch(r'【素養】計算 \((3x^2-2x+1)\div(3x+4)\) 的商式為 \(Q\)，餘式為 \(R\)，則下列何者正確？',[r'\(Q=x+\dfrac{2}{3}\)，\(R=-\dfrac{5}{3}\)',r'\(Q=x+2\)，\(R=-7\)',r'\(Q=x-2\)，\(R=9\)',r'\(Q=x-2\)，\(R=-7\)'],3,r'以長除法計算得 \(Q=x-2\)，\(R=9\)。')
ch('【素養】下列哪一個選項中的等式不成立？',[r'\(\sqrt{(-3)^6}=(-3)^3\)',r'\(\sqrt{(-5)^8}=(-5)^4\)',r'\(\sqrt{5^4\times7^{12}}=5^2\times7^6\)',r'\(\sqrt{(-3)^6(-5)^{10}}=(-3)^3\times(-5)^5\)'],1,r'(A) \(\sqrt{(-3)^6}=\sqrt{3^6}=3^3\neq(-3)^3\)。')
ch('【素養】下列 4 個數中，哪一個不介於 16 與 17 之間？',[r'\(\sqrt{260}\)',r'\(\sqrt{270}\)',r'\(\sqrt{280}\)',r'\(\sqrt{290}\)'],4,r'因為 \(16^2=256\)，\(17^2=289\)，所以 \(\sqrt{290}\) 不介於 16 與 17 之間。')
endp()

sec('第6回 2-2 根式的運算')
ch(r'如附圖，已知長方形的長是 \(\sqrt{14}\) 公分，寬是 \(\sqrt{5}\) 公分，則此長方形的面積為多少平方公分？',[r'\(\sqrt{38}\)',r'\(\sqrt{70}\)',r'\(14\sqrt{5}\)',r'\(5\sqrt{14}\)'],2,r'\(\sqrt{14}\times\sqrt{5}=\sqrt{14\times5}=\sqrt{70}\)（平方公分）。',img=(11,385,378,512,442))
ch(r'計算 \(\sqrt{\dfrac{7}{3}}\div\dfrac{\sqrt{5}}{\sqrt{15}}\) 的結果為下列何者？',[r'\(\sqrt{3}\)',r'\(\sqrt{5}\)',r'\(\sqrt{7}\)',r'\(\dfrac{\sqrt{7}}{3}\)'],3,r'原式＝\(\sqrt{\dfrac{7}{3}}\div\sqrt{\dfrac{5}{15}}=\sqrt{\dfrac{7}{3}\times\dfrac{15}{5}}=\sqrt{7}\)。')
ch('下列根式中，哪一個是最簡根式？',[r'\(\dfrac{2}{5}\sqrt{15}\)',r'\(\sqrt{\dfrac{5}{7}}\)',r'\(\dfrac{\sqrt{24}}{3}\)',r'\(\sqrt{3.2}\)'],1,r'\(\dfrac{2}{5}\sqrt{15}\) 是最簡根式；\(\sqrt{\dfrac{5}{7}}\) 有分數、\(\dfrac{\sqrt{24}}{3}=\dfrac{2\sqrt{6}}{3}\)、\(\sqrt{3.2}\) 有小數，都不是最簡根式。')
ch(r'將 \(\sqrt{2^5\times5^3}\) 化為最簡根式 \(a\sqrt{b}\)，則 \(a+b=\)？',['20','30','40','50'],2,r'\(\sqrt{2^5\times5^3}=\sqrt{2^4\times2\times5^2\times5}=2^2\times5\times\sqrt{2\times5}=20\sqrt{10}\)，所以 \(a=20\)，\(b=10\)，\(a+b=30\)。')
ch(r'【素養】計算 \(\sqrt{\dfrac{343}{4}}\div\sqrt{\dfrac{7}{32}}\) 的結果並化為最簡根式為下列何者？',[r'\(98\sqrt{2}\)','28',r'\(7\sqrt{8}\)',r'\(14\sqrt{2}\)'],4,r'原式＝\(\sqrt{\dfrac{343}{4}\times\dfrac{32}{7}}=\sqrt{49\times8}=\sqrt{7^2\times2^2\times2}=14\sqrt{2}\)。')
ch(r'【素養】已知 \(a=5\sqrt{6}\)，\(b=6\sqrt{5}\)，則下列 \(a\)、\(b\) 大小關係何者正確？',[r'\(a<b\)',r'\(a=b\)',r'\(a>b\)',r'\(a^2=b^2\)'],1,r'\(a^2=(5\sqrt{6})^2=25\times6=150\)，\(b^2=(6\sqrt{5})^2=36\times5=180\)，因為 \(a^2<b^2\)，且 \(a\)、\(b\) 皆為正數，所以 \(a<b\)。')
ch(r'【素養】下列有關甲、乙兩個運算過程何者正確？甲：\(-\dfrac{4}{3}\sqrt{3}\times(-6)=\left(-\dfrac{4}{3}\right)\times\sqrt{3}\times(-6)=\left(-\dfrac{4}{3}\right)\times(-6)\times\sqrt{3}=8\sqrt{3}\)；乙：\((-4\sqrt{3})\div6=-\dfrac{4}{6}\sqrt{3}=-\dfrac{2}{3}\sqrt{3}=-2\)',['甲、乙皆正確','甲、乙皆錯誤','甲正確、乙錯誤','甲錯誤、乙正確'],3,r'乙：\(-\dfrac{2}{3}\sqrt{3}\neq-2\)，故甲正確、乙錯誤。')
ch(r'【素養】將 \(\sqrt{0.9}\) 化為最簡根式為下列何者？',[r'\(\dfrac{\sqrt{3}}{10}\)',r'\(\dfrac{3}{10}\)',r'\(\dfrac{3\sqrt{10}}{10}\)',r'\(\dfrac{3}{\sqrt{10}}\)'],3,r'\(\sqrt{0.9}=\sqrt{\dfrac{9}{10}}=\dfrac{\sqrt{9}}{\sqrt{10}}=\dfrac{3}{\sqrt{10}}=\dfrac{3\sqrt{10}}{10}\)。')
ch(r'【素養】計算 \(5\sqrt{3}+3\sqrt{5}-2\sqrt{3}-7\sqrt{5}\) 的結果並化為最簡根式為下列何者？',[r'\(-\sqrt{2}\)',r'\(\sqrt{2}\)',r'\(3\sqrt{3}-4\sqrt{5}\)',r'\(3\sqrt{3}-4\)'],3,r'原式＝\((5\sqrt{3}-2\sqrt{3})+(3\sqrt{5}-7\sqrt{5})=3\sqrt{3}-4\sqrt{5}\)。')
ch(r'【素養】算式 \((\sqrt{2}-1)(\sqrt{6}-\sqrt{3})\) 之值為何？',[r'\(3\sqrt{3}-2\sqrt{6}\)',r'\(\sqrt{3}\)',r'\(3\sqrt{3}-\sqrt{6}\)',r'\(3\sqrt{3}\)'],1,r'原式＝\(\sqrt{12}-\sqrt{6}-\sqrt{6}+\sqrt{3}=2\sqrt{3}-2\sqrt{6}+\sqrt{3}=3\sqrt{3}-2\sqrt{6}\)。')
ch(r'【素養】利用乘法公式展開 \((3-2\sqrt{5})^2\)，並化簡得 \(a-b\sqrt{5}\)，則 \(a+b\) 之值為何？',['12','17','29','41'],4,r'\((3-2\sqrt{5})^2=3^2-2\times3\times2\sqrt{5}+(2\sqrt{5})^2=9-12\sqrt{5}+20=29-12\sqrt{5}\)，\(a=29\)，\(b=12\)，\(a+b=41\)。')
ch(r'【素養】如附圖，有一梯形 \(ABCD\)，上底 \(\overline{AD}=\sqrt{7}\)，下底 \(\overline{BC}=5\)，高 \(\overline{AH}=5-\sqrt{7}\)，則此梯形 \(ABCD\) 的面積化成最簡根式為多少平方單位？〔梯形面積＝（上底＋下底）×高×\(\dfrac{1}{2}\)〕',['7','9','18',r'\(\sqrt{7}+5\)'],2,r'面積＝\((\sqrt{7}+5)(5-\sqrt{7})\times\dfrac{1}{2}=[5^2-(\sqrt{7})^2]\times\dfrac{1}{2}=(25-7)\times\dfrac{1}{2}=9\)（平方單位）。',img=(12,410,52,512,142))
endp()

sec('第7回 2-3 畢氏定理')
ch(r'如附圖，已知直角三角形的兩股長為 5、13，斜邊長為 \(c\)，則 \(c=\)？',['12','15',r'\(\sqrt{184}\)',r'\(\sqrt{194}\)'],4,r'\(c^2=5^2+13^2=25+169=194\)，因為 \(c>0\)，所以 \(c=\sqrt{194}\)。',img=(13,408,378,505,432))
ch('如附圖，已知直角三角形一股長為 8，斜邊長為 17，則另一股長為多少？',['12','13','14','15'],4,r'設另一股長為 \(a\)，\(a^2+8^2=17^2\Rightarrow a^2=289-64=225\)，因為 \(a>0\)，所以 \(a=15\)。',img=(13,398,518,505,588))
ch(r'附圖是陽明公園一個溜滑梯的側面圖，滑道與樓梯成直角，直角三角形的三邊長分別為 10、24、26，則溜滑梯的高 \(h\) 為多少？',[r'\(\dfrac{60}{13}\)',r'\(\dfrac{120}{13}\)','13','15'],2,r'\(\dfrac{1}{2}\times26\times h=\dfrac{1}{2}\times10\times24\Rightarrow h=\dfrac{10\times24}{26}=\dfrac{120}{13}\)。',img=(13,388,683,512,742))
ch(r'【素養】如附圖，四邊形 \(ABCD\) 中，\(\angle A=\angle C=90^\circ\)。已知 \(\overline{AB}=5\)，\(\overline{AD}=7\)，\(\overline{BC}=4\)，則下列何者正確？',[r'\(\overline{BD}=8\)',r'\(\overline{BD}=9\)',r'\(\overline{CD}=\sqrt{58}\)',r'\(\overline{CD}=\sqrt{59}\)'],3,r'\(\overline{BD}^2=5^2+7^2=25+49=74\Rightarrow\overline{BD}=\sqrt{74}\)，\(\overline{CD}^2=(\sqrt{74})^2-4^2=74-16=58\Rightarrow\overline{CD}=\sqrt{58}\)。',img=(13,412,883,512,968))
ch(r'【素養】如附圖，\(\triangle ABC\) 中，\(\overline{AH}\perp\overline{BC}\)，\(\overline{AB}=20\)，\(\overline{AC}=2\sqrt{89}\)，\(\overline{AH}=16\)，求 \(\overline{BC}=\)？',['20','21','22','24'],3,r'\(\overline{BH}^2=20^2-16^2=400-256=144\Rightarrow\overline{BH}=12\)；\(\overline{CH}^2=(2\sqrt{89})^2-16^2=356-256=100\Rightarrow\overline{CH}=10\)；\(\overline{BC}=\overline{BH}+\overline{CH}=12+10=22\)。',img=(13,395,1122,512,1222))
ch('【素養】如附圖，古早味紅茶的容器為一個直圓柱體，上方杯蓋中央有一小孔，將一支長 21 公分的吸管從中央小孔插入杯中底部邊緣，杯子底圓直徑為 10 公分，高度為 12 公分。吸管露出杯口外的長度為多少公分？（不考慮吸管的粗細）',['7','8','9','10'],2,r'設吸管從杯中心點到杯底邊緣的長度為 \(x\) 公分，半徑＝\(10\div2=5\)，\(x^2=5^2+12^2=25+144=169\)，因為 \(x>0\)，故得 \(x=13\)，所以吸管露出杯口外的長度＝\(21-13=8\)（公分）。',img=(13,458,1358,518,1452))
ch('【素養】如附圖，雲梯原長為 30 公尺，已知雲梯底部與建築物水平距離為 10 公尺，若雲梯長縮短為 26 公尺，則雲梯所能到達建築物的高度比原來少幾公尺？',[r'\(20\sqrt{2}-24\)',r'\(24-20\sqrt{2}\)',r'\(20\sqrt{3}-24\)','4'],1,r'原高度 \(h\) 為 \(\sqrt{30^2-10^2}=\sqrt{800}=20\sqrt{2}\)（公尺），縮短後高度為 \(\sqrt{26^2-10^2}=\sqrt{576}=24\)（公尺），減少的高度為 \((20\sqrt{2}-24)\) 公尺。',img=(13,890,343,1000,502))
ch(r'【素養】如附圖，博士為閃星手機製造商設計了一款新型的長方形摺疊手機。合起來時，長為 6 吋，寬為 3 吋，其螢幕尺寸（即對角線的長度）為 \(a\) 吋；展開時，長為 6 吋，寬為 6 吋，其螢幕尺寸為 \(b\) 吋，則 \(\dfrac{b}{a}\) 之值為何？',[r'\(\dfrac{3\sqrt{10}}{5}\)',r'\(\dfrac{2\sqrt{10}}{5}\)','2',r'\(\sqrt{2}\)'],2,r'展開前對角線長 \(a=\sqrt{6^2+3^2}=3\sqrt{5}\)（吋），展開後對角線長 \(b=\sqrt{6^2+6^2}=6\sqrt{2}\)（吋），\(\dfrac{b}{a}=\dfrac{6\sqrt{2}}{3\sqrt{5}}=\dfrac{2\sqrt{10}}{5}\)。',img=(13,858,648,1002,772))
ch(r'【素養】已知坐標平面上 \(A(4,3)\)、\(B(-6,3)\)、\(C(4,-5)\) 三點，則 \(\overline{AB}+\overline{AC}=\)？',['18','17','16','15'],1,r'\(\overline{AB}=|4-(-6)|=10\)，\(\overline{AC}=|3-(-5)|=8\)，所求＝\(10+8=18\)。')
ch('【素養】如附圖，某款桌上型電腦的螢幕是長方形，其長寬比為 4：3，若對角線長為 20 吋，則桌上型電腦的螢幕面積是多少平方吋？',['96','128','144','192'],4,r'設此電腦螢幕的長為 \(4k\) 吋，寬為 \(3k\) 吋，\(k\neq0\)，\((4k)^2+(3k)^2=20^2\Rightarrow25k^2=400\Rightarrow k^2=16\)，故此電腦螢幕的面積為 \(4k\times3k=12k^2=12\times16=192\)（平方吋）。',img=(13,900,1322,1002,1408))
ch(r'【素養】已知坐標平面上 \(D(-2,1)\)、\(E(-7,10)\) 兩點，則 \(\overline{DE}\) 的長為何？',[r'\(\sqrt{106}\)',r'\(\sqrt{146}\)',r'\(9\sqrt{2}\)','9'],1,r'\(\overline{DE}=\sqrt{[(-2)-(-7)]^2+(1-10)^2}=\sqrt{25+81}=\sqrt{106}\)。')
ch(r'【素養】如附圖，\(O\) 點為數線上的原點，\(A\) 點的坐標為 2，在直角三角形 \(OAB\) 與直角三角形 \(OBC\) 中，\(\overline{AB}=\overline{BC}=1\)，若數線上有一點 \(D\)，且 \(\overline{OD}=\overline{OC}\)，則 \(D\) 點的坐標為何？',['－2',r'\(-\sqrt{5}\)',r'\(-\sqrt{6}\)',r'\(-2\sqrt{2}\)'],3,r'\(\overline{OB}=\sqrt{2^2+1^2}=\sqrt{5}\)，\(\overline{OC}=\sqrt{(\sqrt{5})^2+1^2}=\sqrt{6}\)，故 \(D\) 點坐標為 \(-\sqrt{6}\)。',img=(14,365,255,512,340))
endp()

sec('第8回 3-1 提公因式與乘法公式作因式分解')
ch(r'下列甲、乙有關因式、倍式的敘述何者正確？甲：\(x-1\) 是 \(3x^2-x-2\) 的因式；乙：\(x^2+4\) 是 \(x+2\) 的倍式',['甲、乙都正確','甲、乙都錯誤','甲正確、乙錯誤','甲錯誤、乙正確'],3,r'甲：\((3x^2-x-2)\div(x-1)=3x+2\)，餘式為 0，正確；乙：\((x^2+4)\div(x+2)=x-2\cdots\cdots8\)，不能整除，錯誤。')
ch(r'已知 \(2x^2-5x-3=(x-3)(2x+1)\)，則下列敘述何者錯誤？',[r'\(2x^2-5x-3\) 是 \(x-3\) 的倍式',r'\(2x+1\) 是 \(2x^2-5x-3\) 的因式',r'\(2x^2-5x-3\) 是 \(1+2x\) 的倍式',r'\(x-3\) 是 \(2x+1\) 的因式'],4,r'(D) \(x-3\) 不是 \(2x+1\) 的因式。')
ch(r'已知 \(3x^2-15x-42=3(x+2)(x-7)\)，則下列何者是 \(3x^2-15x-42\) 的因式？',[r'\(3x+6\)',r'\(3x+2\)',r'\(3x-7\)',r'\(x+7\)'],1,r'\(3x+6=3(x+2)\) 是 \(3x^2-15x-42\) 的因式。')
ch(r'若多項式 \(A\) 為 \((x+2)(x+3)\)，多項式 \(B\) 為 \((x+3)(x-1)\)，則多項式 \(A\) 與 \(B\) 的公因式為何？',[r'\(x-1\)',r'\(x+2\)',r'\(x+3\)',r'\(2x+1\)'],3,r'\(A\) 與 \(B\) 的公因式為 \(x+3\)。')
ch(r'【素養】下列何者不是 \(4x^2-2x\) 的因式？',[r'\(x\)',r'\(-2x\)',r'\(1-2x\)',r'\(2x+1\)'],4,r'\(4x^2-2x=2x(2x-1)=-2x(-2x+1)=-2x(1-2x)\)，故選(D)。')
ch(r'【素養】因式分解 \(x^2-3x(x-3)\) 的結果為下列何者？',[r'\(x(2x+9)\)',r'\(-x(2x-9)\)',r'\((x-3)(x+1)\)',r'\((x-3)(x-1)\)'],2,r'\(x^2-3x(x-3)=x[x-3(x-3)]=x(x-3x+9)=x(-2x+9)=-x(2x-9)\)。')
ch(r'【素養】已知 \((x+7)(5x-3)-(5x-3)\)，可因式分解成 \((5x+a)(x+b)\)，其中 \(a\)、\(b\) 均為整數，則 \(a+b\) 之值為何？',['3','4','6','9'],1,r'原式＝\((5x-3)[(x+7)-1]=(5x-3)(x+6)\)，故 \(a=-3\)，\(b=6\)，\(a+b=(-3)+6=3\)。')
ch(r'【素養】因式分解 \((5-3x)^2-(3x-5)(x-3)\) 的結果為下列何者？',[r'\(2(3x-5)(x+1)\)',r'\(2(3x-5)(x+4)\)',r'\(2(3x-5)(x-1)\)',r'\(-4(3x-5)(x+2)\)'],3,r'原式＝\((3x-5)^2-(3x-5)(x-3)=(3x-5)[(3x-5)-(x-3)]=(3x-5)(2x-2)=2(3x-5)(x-1)\)。')
ch(r'【素養】因式分解 \((x-1)(2x+1)-(x-1)(x+4)\) 的結果為下列何者？',[r'\((x+1)(x+3)\)',r'\((x-1)(x+3)\)',r'\((x+1)(x-3)\)',r'\((x-1)(x-3)\)'],4,r'原式＝\((x-1)[(2x+1)-(x+4)]=(x-1)(2x+1-x-4)=(x-1)(x-3)\)。')
ch(r'【素養】如附圖，將一張邊長為 \(5x+2\) 的正方形紙片，中間剪去一個邊長為 \(3x\) 的正方形，而剩餘的面積會與一個長方形面積相等，若此長方形其中一個邊長為 \(4x+1\)，而另一邊長為何？',[r'\(4x\)',r'\(4x+2\)',r'\(4x+4\)',r'\(2x+2\)'],3,r'\((5x+2)^2-(3x)^2=[(5x+2)+3x][(5x+2)-3x]=(8x+2)(2x+2)=2(4x+1)(2x+2)=(4x+1)(4x+4)\)，故另一邊長為 \(4x+4\)。',img=(15,885,985,1002,1072))
ch(r'【素養】下列何者不是 \(25-(3y+2)^2\) 的因式？',[r'\(3y+7\)',r'\(3y-3\)',r'\(y-1\)',r'\(y+1\)'],4,r'原式＝\(5^2-(3y+2)^2=[5+(3y+2)][5-(3y+2)]=(3y+7)(-3y+3)=-3(3y+7)(y-1)\)，故選(D)。')
ch(r'【素養】附圖是四個面積分別為 \(10x\)、\(4x^2\)、\(10x\) 和 25 的圖形所組成的一個大正方形，則此大正方形的邊長為何？',[r'\(2x+5\)',r'\(2x+10\)',r'\(4x+5\)',r'\(4x+10\)'],1,r'面積＝\(4x^2+2\cdot10x+25=(2x)^2+2\cdot2x\cdot5+5^2=(2x+5)^2\)，故正方形邊長為 \(2x+5\)。',img=(16,388,52,512,178))
endp()

sec('第9回 3-2 利用十字交乘法因式分解')
ch(r'下列何者為 \(x^2+10x+16\) 的因式？',[r'\(x+2\)',r'\(x+4\)',r'\(x+6\)',r'\(x+10\)'],1,r'利用十字交乘法：\(x^2+10x+16=(x+2)(x+8)\)。')
ch(r'因式分解 \(x^2-13x+42\) 得 \((x+a)(x+b)\)，則 \(a+b\) 之值為何？',['13','－13','42','－42'],2,r'\(x^2-13x+42=(x-6)(x-7)\)，故 \(a=-6\)，\(b=-7\) 或 \(a=-7\)，\(b=-6\)，\(a+b=-13\)。')
ch(r'下列利用十字交乘法因式分解 \(2x^2-11x+15\) 的過程，何者正確？（每個選項表示第一列 \(x\) 配一個常數、第二列 \(2x\) 配一個常數）',[r'\(x\) 配 \(-1\)，\(2x\) 配 \(-15\)',r'\(x\) 配 \(-3\)，\(2x\) 配 \(-5\)',r'\(x\) 配 \(-15\)，\(2x\) 配 \(-1\)',r'\(x\) 配 \(-5\)，\(2x\) 配 \(-3\)'],2,r'\(2x^2-11x+15=(x-3)(2x-5)\)，交叉相乘 \(-6x-5x=-11x\)，故選(B)。',img=(17,128,882,512,1035))
ch(r'因式分解 \(5x^2+4x-12\) 的結果為下列何者？',[r'\((x+4)(5x-3)\)',r'\((x-4)(5x+3)\)',r'\((x+2)(5x-6)\)',r'\((x-2)(5x+6)\)'],3,r'利用十字交乘法：\(5x^2+4x-12=(x+2)(5x-6)\)。')
ch(r'【素養】附圖長方形面積為 \((x^2-x-12)\) 平方單位，若長、寬皆為 \(x\) 的一次多項式且係數皆為整數，已知 \(x>4\)，則此長方形的周長為何？',[r'\(2x-8\)',r'\(2x+6\)',r'\(4x-2\)',r'\(4x+14\)'],3,r'\(x^2-x-12=(x+3)(x-4)\)，長、寬各為 \((x+3)\)、\((x-4)\)，周長為 \(2[(x+3)+(x-4)]=2(2x-1)=4x-2\)。',img=(17,408,1310,508,1368))
ch(r'【素養】已知 \(4x^2+16x-84\) 可因式分解成 \(a(x+b)(x-3)\)，則 \(a+b=\)？',['8','9','10','11'],4,r'原式＝\(4(x^2+4x-21)=4(x+7)(x-3)\)，故 \(a=4\)，\(b=7\)，\(a+b=4+7=11\)。')
ch(r'【素養】下列何者不是 \(6x^2+40x-14\) 的因式？',[r'\(2x+14\)',r'\(3x+7\)',r'\(3x-1\)',r'\(6x-2\)'],2,r'原式＝\(2(3x^2+20x-7)=2(x+7)(3x-1)\)，故 \(3x+7\) 不是其因式。')
ch(r'【素養】下列何者為 \(-2x^2+3x+2\) 的因式？',[r'\(x+1\)',r'\(x-2\)',r'\(x+2\)',r'\(2x-1\)'],2,r'原式＝\(-(2x^2-3x-2)=-(2x+1)(x-2)\)。')
ch(r'【素養】因式分解 \(16x^2-24x+9\) 得 \((ax+b)^2\)，且 \(a>0\)，則 \(a+b\) 之值為何？',['7','－7','1','－1'],3,r'原式＝\((4x-3)^2\)，\(a=4\)，\(b=-3\)，則 \(a+b=4+(-3)=1\)。')
ch(r'【素養】如附圖，長方形的長為 \(ax+b\)，寬為 \(cx-d\)，面積為 \((6x^2-x-15)\) 平方單位，其中 \(a\)、\(b\)、\(c\)、\(d\) 皆為正整數，則 \(a+b+c+d\) 的值為何？',['9','10','13','15'],3,r'\(6x^2-x-15=(3x-5)(2x+3)\Rightarrow a=2\)，\(b=3\)，\(c=3\)，\(d=5\)，\(a+b+c+d=2+3+3+5=13\)。',img=(17,868,1255,1002,1318))
ch(r'【素養】若 \(9x^2+12x-5\) 與 \(6x^2-23x+7\) 的公因式為一次式 \(ax-1\)，則 \(a\) 的值為何？',['1','2','3','6'],3,r'\(9x^2+12x-5=(3x-1)(3x+5)\)，\(6x^2-23x+7=(3x-1)(2x-7)\)，公因式為 \(3x-1\Rightarrow a=3\)。')
ch(r'【素養】妙麗利用十字交乘法作 \(x^2+kx+12\) 的因式分解得 \((x+a)(x+b)\)，則 \(k\) 值不可能為下列何者？',['－7','－8','13','6'],4,r'\(ab=12\) 時，\((a,b)\) 可為 (1,12)、(2,6)、(3,4)、(－1,－12)、(－2,－6)、(－3,－4)，\(k=a+b\) 可為 13、8、7、－13、－8、－7，故選(D)。')
endp()

sec('第10回 2-2～3-2 複習')
ch('下列敘述何者正確？',[r'\(\sqrt{5}+\sqrt{3}=\sqrt{5+3}\)',r'\(\sqrt{5}-\sqrt{3}=\sqrt{5-3}\)',r'\(\sqrt{5}\times\sqrt{3}=\sqrt{5\times3}\)',r'\(\sqrt{5}\div\sqrt{3}=\sqrt{3\div5}\)'],3,r'(A)(B) \(\sqrt{5}\)、\(\sqrt{3}\) 不是同類方根，無法再合併化簡；(D) \(\sqrt{5}\div\sqrt{3}=\sqrt{5\div3}\)。')
ch(r'將 \(\dfrac{\sqrt{2}}{\sqrt{6}-\sqrt{5}}\) 化為最簡根式得 \(a\sqrt{b}+\sqrt{c}\)，其中 \(a\)、\(b\)、\(c\) 皆為正整數，則 \(a+b+c=\)？',['16','15','14','13'],2,r'原式＝\(\dfrac{\sqrt{2}(\sqrt{6}+\sqrt{5})}{(\sqrt{6}-\sqrt{5})(\sqrt{6}+\sqrt{5})}=\sqrt{12}+\sqrt{10}=2\sqrt{3}+\sqrt{10}\)，故 \(a=2\)，\(b=3\)，\(c=10\)，\(a+b+c=15\)。')
ch(r'已知坐標平面上 \(A(3,2)\)、\(B(-7,-3)\) 兩點，則 \(\overline{AB}\) 的長為何？',[r'\(5\sqrt{5}\)',r'\(\sqrt{41}\)',r'\(\sqrt{101}\)','15'],1,r'\(\overline{AB}=\sqrt{[3-(-7)]^2+[2-(-3)]^2}=\sqrt{100+25}=\sqrt{125}=5\sqrt{5}\)。')
ch(r'下列何者為多項式 \((x+7)(x-5)\) 與 \((x-5)(x-7)\) 的公因式？',[r'\((x+7)(x-7)\)',r'\(x+7\)',r'\(x+5\)',r'\(x-5\)'],4,r'公因式為 \(x-5\)。')
ch(r'【素養】下列何者不是多項式 \((2x-1)(2x+1)\) 的因式？',[r'\((2x+1)^2\)',r'\(2x-1\)',r'\(2x+1\)',r'\(4x^2-1\)'],1,r'\((2x+1)^2\) 不是 \((2x-1)(2x+1)\) 的因式。')
ch(r'【素養】已知 \(\sqrt{6}\approx2.449\)，\(\sqrt{60}\approx7.746\)，利用根式的運算規則求 \(\sqrt{0.6}\) 的近似值為何？',['0.2449','0.02449','0.7746','0.07746'],3,r'\(\sqrt{0.6}=\sqrt{\dfrac{60}{100}}=\dfrac{\sqrt{60}}{10}\approx\dfrac{7.746}{10}=0.7746\)。')
ch(r'【素養】若一正方形的面積為 80 平方公分，周長為 \(x\) 公分，則 \(x\) 介於哪兩個連續整數之間？（\(\sqrt{5}\approx2.236\)）',['32、33','33、34','34、35','35、36'],4,r'邊長＝\(\sqrt{80}=4\sqrt{5}\)，周長 \(x=4\times4\sqrt{5}=16\sqrt{5}\approx16\times2.236=35.776\)，\(x\) 介於 35、36 之間。')
ch('【素養】如附圖，在直角三角形 ABC 中，以各邊為邊長所作的正方形分別是甲、乙、丙，若甲的面積為 6 平方單位，乙的面積為 4 平方單位，則丙的面積為多少平方單位？',['8','10','24','52'],2,r'根據畢氏定理：\(\overline{AC}^2+\overline{BC}^2=\overline{AB}^2\Rightarrow\) 甲面積＋乙面積＝丙面積 \(\Rightarrow\) 丙面積＝\(6+4=10\)（平方單位）。',img=(19,875,580,1000,690))
ch(r'【素養】如附圖，直角三角形 \(ABC\) 中，\(\overline{AD}\) 為斜邊上的高，若 \(\overline{AB}=16\)，\(\overline{BC}=20\)，則 \(\overline{AD}\) 的長為何？',[r'\(\dfrac{24}{5}\)',r'\(\dfrac{36}{5}\)',r'\(\dfrac{48}{5}\)','10'],3,r'\(\overline{AC}=\sqrt{20^2-16^2}=12\)，\(\overline{AD}=\dfrac{16\times12}{20}=\dfrac{48}{5}\)。',img=(19,872,882,1002,982))
ch(r'【素養】已知 \(x-3\) 是 \(2x^2+x-k\) 的因式，則下列何者也是 \(2x^2+x-k\) 的因式？',[r'\(2x+5\)',r'\(2x+7\)',r'\(x+7\)',r'\(x-5\)'],2,r'以長除法計算 \((2x^2+x-k)\div(x-3)\)，商式為 \(2x+7\)，餘式為 \(21-k=0\)，故 \(2x+7\) 也是其因式。')
ch(r'【素養】有兩個多項式 \(4x^2+11x+6\) 與 \(16x^2+24x+9\)，則這兩個多項式的公因式為何？',[r'\(x+2\)',r'\(x+3\)',r'\(4x+2\)',r'\(4x+3\)'],4,r'\(4x^2+11x+6=(4x+3)(x+2)\)，\(16x^2+24x+9=(4x+3)^2\)，公因式為 \(4x+3\)。')
ch(r'【素養】多項式 \(26x^2-25x-21\) 可因式分解成 \((2x-a)(bx+c)\)，其中 \(a\)、\(b\)、\(c\) 均為整數，則 \(a+b+c\) 的值為何？',['20','21','23','25'],3,r'原式＝\((2x-3)(13x+7)\)，\(a=3\)，\(b=13\)，\(c=7\)，\(a+b+c=3+13+7=23\)。')
endp()

sec('第11回 4-1 因式分解法解一元二次方程式')
ch('下列何者為一元二次方程式？',[r'\(3x^2-2x-1\)',r'\(x^3=x^2-x\)',r'\(2x^2-3x=2(x^2+1)\)',r'\(x^2-2x=3\)'],4,r'(A) 為一元二次式；(B) 為一元三次方程式；(C) 原式 \(\Rightarrow2x^2-3x-2x^2-2=0\Rightarrow-3x-2=0\)，為一元一次方程式。')
ch(r'判別 \(x=2\) 是下列哪一個一元二次方程式的解？',[r'\((x+2)(x-1)=2\)',r'\(x^2+2x-6=0\)',r'\(x^2-3x+4=0\)',r'\(x^2-12x+20=0\)'],4,r'(A) \((2+2)(2-1)=4\neq2\)；(B) \(2^2+2\times2-6=2\neq0\)；(C) \(2^2-3\times2+4=2\neq0\)；(D) \(2^2-12\times2+20=0\)。')
ch(r'若 \(x=-2\) 是 \(3x^2-mx+2=0\) 的一個解，則 \(m\) 的值為何？',['－5','－7','5','7'],2,r'\(x=-2\) 代入得 \(3(-2)^2-m(-2)+2=0\Rightarrow12+2m+2=0\Rightarrow m=-7\)。')
ch(r'【素養】若 \(a\)、\(b\) 為方程式 \((2x+3)(x-1)=0\) 的兩個解，則 \(a+b\) 之值為何？',[r'\(\dfrac{3}{2}\)',r'\(\dfrac{1}{2}\)',r'\(-\dfrac{1}{2}\)',r'\(-\dfrac{3}{2}\)'],3,r'\(2x+3=0\) 或 \(x-1=0\Rightarrow x=-\dfrac{3}{2}\) 或 \(x=1\)，\(a+b=\left(-\dfrac{3}{2}\right)+1=-\dfrac{1}{2}\)。')
ch(r'【素養】若 \(x=0\) 為一元二次方程式 \(2x^2-5x+2a-4=0\) 的一個解，則 \(a\) 的值為何？',['－2','2',r'\(\dfrac{5}{2}\)','4'],2,r'\(x=0\) 代入得 \(2a-4=0\Rightarrow a=2\)。')
ch(r'【素養】關於方程式 \((2x-7)(3x-1)=(2x-7)(2x-3)\) 的解，下列敘述何者正確？',['有一個解介於 1 和 3 之間','有一個解介於 3 和 4 之間','兩個解皆正數','兩個解皆負數'],2,r'原式 \(\Rightarrow(2x-7)(3x-1)-(2x-7)(2x-3)=0\Rightarrow(2x-7)[(3x-1)-(2x-3)]=0\Rightarrow(2x-7)(x+2)=0\Rightarrow x=\dfrac{7}{2}\) 或 \(x=-2\)。')
ch(r'【素養】有關甲、乙解一元二次方程式的敘述何者正確？甲：\(5x(3x+2)=7(3x+2)\)，將等號兩邊同除以 \(3x+2\) 得 \(5x=7\)，\(x=\dfrac{7}{5}\)；乙：\(5x(3x+2)-7(3x+2)=0\Rightarrow(3x+2)(5x-7)=0\Rightarrow3x+2=0\) 或 \(5x-7=0\Rightarrow x=-\dfrac{2}{3}\) 或 \(x=\dfrac{7}{5}\)',['甲、乙都正確','甲、乙皆錯誤','甲正確，乙錯誤','甲錯誤，乙正確'],4,r'當 \(3x+2=0\) 時，不可以兩邊同除以 \(3x+2\)，故甲錯誤，乙正確。')
ch(r'【素養】解一元二次方程式 \((x+3)^2-4=0\) 的兩個解中，較大的一個解為何？',['－1','－5','1','5'],1,r'\((x+3)^2-2^2=0\Rightarrow[(x+3)+2][(x+3)-2]=0\Rightarrow(x+5)(x+1)=0\Rightarrow x=-5\) 或 \(x=-1\)，較大的一個解為 －1。')
ch(r'【素養】若一元二次方程式 \(x^2+14x+49=0\) 的兩個解為 \(a\)、\(b\)，則 \(a+b\) 之值為何？',['7','14','－7','－14'],4,r'\(x^2+14x+49=0\Rightarrow(x+7)^2=0\Rightarrow x=-7\)（重根），\(a+b=(-7)+(-7)=-14\)。')
ch(r'【素養】解一元二次方程式 \((x+1)(x-5)=16\) 得 \(x=\)？',[r'\(x=-3\) 或 \(x=7\)',r'\(x=1\) 或 \(x=13\)',r'\(x=0\) 或 \(x=21\)',r'\(x=15\) 或 \(x=6\)'],1,r'\(x^2-4x-5=16\Rightarrow x^2-4x-21=0\Rightarrow(x+3)(x-7)=0\Rightarrow x=-3\) 或 \(x=7\)。')
ch(r'【素養】解一元二次方程式 \(\dfrac{1}{2}x^2+\dfrac{11}{6}x+1=0\) 得兩個解為 \(a\)、\(b\)，且 \(a>b\)，則 \(3a+b\) 之值為何？',['－6','－5',r'\(-\dfrac{2}{3}\)',r'\(-9\dfrac{2}{3}\)'],2,r'等號兩邊同乘以 6，\(3x^2+11x+6=0\Rightarrow(x+3)(3x+2)=0\Rightarrow x=-3\) 或 \(x=-\dfrac{2}{3}\)，則 \(a=-\dfrac{2}{3}\)，\(b=-3\)，故 \(3a+b=3\times\left(-\dfrac{2}{3}\right)+(-3)=-5\)。')
ch(r'【素養】若 \(x=2\) 為一元二次方程式 \(x^2-ax-2a=0\) 的一個解，則另一個解為何？',['2','1','－1','－2'],3,r'\(x=2\) 代入得 \(4-2a-2a=0\Rightarrow a=1\)，\(x^2-x-2=0\Rightarrow(x-2)(x+1)=0\Rightarrow x=2\) 或 \(x=-1\)，故另一個解為 －1。')
endp()

sec('第12回 4-2 配方法與公式解')
ch(r'下列何者不是一元二次方程式 \(4x^2=6\) 的解？',[r'\(\dfrac{\sqrt{6}}{2}\)',r'\(\dfrac{\sqrt{3}}{\sqrt{2}}\)',r'\(-\dfrac{\sqrt{6}}{2}\)',r'\(-\sqrt{3}\)'],4,r'\(4x^2=6\Rightarrow x^2=\dfrac{6}{4}\Rightarrow x=\pm\dfrac{\sqrt{6}}{2}=\pm\sqrt{\dfrac{3}{2}}=\pm\dfrac{\sqrt{3}}{\sqrt{2}}\)，故選(D)。')
ch(r'解一元二次方程式 \((x-3)^2=5\)，得 \(x=\)？',[r'\(3\pm\sqrt{5}\)',r'\(-3\pm\sqrt{5}\)',r'\(5\pm\sqrt{3}\)',r'\(-5\pm\sqrt{3}\)'],1,r'\((x-3)^2=5\Rightarrow x-3=\pm\sqrt{5}\Rightarrow x=3\pm\sqrt{5}\)。')
ch(r'已知 \(x^2+20x+a\) 是完全平方式，則 \(a\) 的值為何？',['10','40','100','400'],3,r'\(x^2+20x+a=x^2+2\cdot x\cdot10+10^2\)，故 \(a=10^2=100\)。')
ch(r'若一元二次方程式 \(x^2+4x-2=0\) 可配方化成 \((x+a)^2=b\) 的形式，則下列何者正確？',[r'\((x-2)^2=6\)',r'\((x-2)^2=2\)',r'\((x+2)^2=6\)',r'\((x+2)^2=8\)'],3,r'\(x^2+4x=2\Rightarrow x^2+4x+2^2=2+2^2\Rightarrow(x+2)^2=6\)。')
ch(r'【素養】如附圖，有 1 個邊長為 \(x\) 的正方形與 10 個長為 \(x\)、寬為 1 的長方形，至少還需要幾個邊長為 1 的小正方形，就可以拼成一個大的正方形？',['10','15','20','25'],4,r'\(x^2+10x+\square=x^2+2\cdot x\cdot5+5^2=(x+5)^2\)，故需要 \(5^2=25\) 個小正方形。',img=(23,165,1192,402,1285))
ch(r'【素養】若以配方法解一元二次方程式 \(x^2-4x-896=0\) 得兩個解為 \(a\)、\(b\)，且 \(a>b\)，則 \(2a+b\) 之值為何？',['36','34','32','28'],1,r'\(x^2-4x=896\Rightarrow x^2-4x+2^2=896+2^2\Rightarrow(x-2)^2=900\Rightarrow x-2=\pm30\Rightarrow x=32\) 或 \(x=-28\)，\(2a+b=2\times32+(-28)=36\)。')
ch(r'【素養】若方程式 \(x^2-12x+15=0\) 可配方化成 \((x-p)^2=k\) 的形式，則 \(p+k\) 的值是多少？',['27','15','－27','－45'],1,r'\(x^2-12x=-15\Rightarrow x^2-12x+6^2=-15+6^2\Rightarrow(x-6)^2=21\)，故 \(p=6\)，\(k=21\)，\(p+k=6+21=27\)。')
ch(r'【素養】解一元二次方程式 \(2x+2x^2=3\)，得 \(x=\)？',[r'\(\dfrac{-1\pm\sqrt{3}}{2}\)',r'\(\dfrac{-1\pm\sqrt{3}}{4}\)',r'\(\dfrac{-1\pm\sqrt{7}}{2}\)',r'\(\dfrac{-1\pm\sqrt{7}}{4}\)'],3,r'\(2x^2+2x=3\Rightarrow x^2+x=\dfrac{3}{2}\Rightarrow x^2+x+\left(\dfrac{1}{2}\right)^2=\dfrac{3}{2}+\left(\dfrac{1}{2}\right)^2\Rightarrow\left(x+\dfrac{1}{2}\right)^2=\dfrac{7}{4}\Rightarrow x+\dfrac{1}{2}=\pm\dfrac{\sqrt{7}}{2}\Rightarrow x=\dfrac{-1\pm\sqrt{7}}{2}\)。')
ch(r'【素養】一元二次方程式 \(x^2-7x+15=0\) 的兩個解為下列哪一種情形？',['兩相異解','重根','無解','相反數'],3,r'\(x^2-7x=-15\Rightarrow x^2-7x+\left(\dfrac{7}{2}\right)^2=-15+\left(\dfrac{7}{2}\right)^2\Rightarrow\left(x-\dfrac{7}{2}\right)^2=-\dfrac{11}{4}\)，故此方程式無解。')
ch(r'【素養】艾美利用公式解，求一元二次方程式 \(3x^2-5x+1=0\)，得 \(x=\dfrac{5\pm\sqrt{k}}{6}\)，則 \(k=\)？',['12','13','17','37'],2,r'令 \(a=3\)，\(b=-5\)，\(c=1\)，\(k=(-5)^2-4\times3\times1=25-12=13\)。')
ch('【素養】下列哪一個一元二次方程式無解？',[r'\(x^2+x+2=0\)',r'\(x^2+x-2=0\)',r'\(x^2-2x-1=0\)',r'\(x^2+2x-1=0\)'],1,r'(A) \(1^2-4\times1\times2=-7<0\)，原方程式無解；(B) \(1^2-4\times1\times(-2)=9\)；(C) \((-2)^2-4\times1\times(-1)=8\)；(D) \(2^2-4\times1\times(-1)=8\)。')
ch(r'【素養】下列甲、乙兩人利用公式解，求一元二次方程式 \(-\dfrac{1}{6}x^2+\dfrac{1}{2}x+\dfrac{1}{3}=0\) 的部分過程，則下列何者正確？甲：等號兩邊同乘以 6 得 \(-x^2+3x+2=0\)，令 \(a=-1\)，\(b=3\)，\(c=2\)，\(b^2-4ac=m\)；乙：等號兩邊同乘以 \(-6\) 得 \(x^2-3x-2=0\)，令 \(a=1\)，\(b=-3\)，\(c=-2\)，\(b^2-4ac=n\)',[r'\(m>n\)',r'\(m=n\)',r'\(m<n\)',r'\(m\)、\(n\) 互為相反數'],2,r'甲：\(m=3^2-4\times(-1)\times2=17\)；乙：\(n=(-3)^2-4\times1\times(-2)=17\)，故 \(m=n\)。')
endp()

sec('第13回 4-3 應用問題')
ch(r'艾美到文具店買原子筆，她買的數量比原子筆的單價少 5，結帳時付了 210 元並找回 6 元。已知每枝原子筆單價 \(x\) 元，則依題意可列出一元二次方程式為何？',[r'\(x(x+5)=210+6\)',r'\(x(x-5)=210+6\)',r'\(x(x+5)=210-6\)',r'\(x(x-5)=210-6\)'],4,r'單價 \(x\) 元，買 \((x-5)\) 枝，\(x(x-5)=210-6\)。')
ch(r'如附圖，有一正方形 \(ABCD\) 與長方形 \(CDEF\) 拼成一個長方形 \(ABFE\)，已知 \(\overline{CF}=7\)，且長方形 \(ABFE\) 的面積為 60 平方單位，則正方形 \(ABCD\) 的邊長為何？',['3','4','5','6'],3,r'設 \(\overline{AB}=x\)，\(x(x+7)=60\Rightarrow x^2+7x-60=0\Rightarrow(x-5)(x+12)=0\Rightarrow x=5\) 或 \(x=-12\)（不合）。',img=(25,405,650,512,718))
ch('有三個連續正整數，它們的平方和為 365，則此連續三個正整數中，最小的數為何？',['10','11','12','13'],1,r'設此三數為 \(x-1\)、\(x\)、\(x+1\)，\((x-1)^2+x^2+(x+1)^2=365\Rightarrow3x^2+2=365\Rightarrow x^2=121\Rightarrow x=\pm11\)（負不合），最小的數為 \(11-1=10\)。')
ch('如附圖，在邊長 27 公尺的正方形草地內部邊緣開闢一橫一直且等寬的道路，已知剩下的草地面積為 576 平方公尺，則道路寬為多少公尺？',['2','3',r'\(\dfrac{3}{2}\)',r'\(\dfrac{5}{2}\)'],2,r'設道路寬為 \(x\) 公尺，\((27-x)^2=576\Rightarrow27-x=24\) 或 \(27-x=-24\Rightarrow x=3\) 或 \(x=51\)（不合）。',img=(25,405,1055,508,1155))
ch('【素養】有一對父子，爸爸的年齡比兒子大 30 歲，3 年前，兒子年齡的平方剛好是爸爸的年齡，則父子兩人現在的年齡和是多少歲？',['42','44','46','48'],4,r'設現在兒子 \(x\) 歲，爸爸為 \((x+30)\) 歲，\(x+30-3=(x-3)^2\Rightarrow x^2-7x-18=0\Rightarrow(x+2)(x-9)=0\Rightarrow x=-2\)（不合）或 \(x=9\)，\((30+9)+9=48\)（歲）。')
ch('【素養】有三個連續正偶數，它們的平方和為 308，則此三數和為多少？',['24','30','36','42'],2,r'設三數為 \(x-2\)、\(x\)、\(x+2\)，\((x-2)^2+x^2+(x+2)^2=308\Rightarrow3x^2+8=308\Rightarrow x^2=100\Rightarrow x=\pm10\)（負不合），三數和為 \(8+10+12=30\)。')
ch(r'【素養】附圖是祖賢為園遊會設計的平面圖，長方形場地的長為 36 公尺、寬為 26 公尺，有 2 條等寬且互相垂直的道路。已知道路與場地的長寬平行，設道路寬為 \(x\) 公尺，若剩下的場地面積為全部面積的 \(\dfrac{25}{39}\) 倍，則依題意可列出一元二次方程式並化簡為何？',[r'\(x^2-62x+336=0\)',r'\(x^2+62x+336=0\)',r'\(x^2-62x-336=0\)',r'\(x^2-62x+936=0\)'],1,r'\((36-x)(26-x)=\dfrac{25}{39}\times36\times26\Rightarrow936-62x+x^2=600\Rightarrow x^2-62x+336=0\)。',img=(25,880,340,1003,442))
ch('【素養】承上題（長 36 公尺、寬 26 公尺的長方形場地，有 2 條等寬且互相垂直的道路，剩下的場地面積為全部面積的 25/39 倍），則道路寬為多少公尺？',['4','4.5','5','6'],4,r'\(x^2-62x+336=0\Rightarrow(x-6)(x-56)=0\Rightarrow x=6\) 或 \(x=56\)（不合）。',img=(25,880,340,1003,442))
ch('【素養】神祕福袋一個賣 200 元，平均每小時可賣 30 個，只要福袋每降價 5 元，平均每小時就會多賣 10 個，已知福袋成本每個 50 元，售價不得低於成本，若每小時的總收入是 12600 元，則福袋的售價為多少元？',['140','160','180','185'],3,r'設降價 \(5x\) 元，平均每小時多賣 \(10x\) 個，\((200-5x)(30+10x)=12600\Rightarrow6000+1850x-50x^2=12600\Rightarrow x^2-37x+132=0\Rightarrow(x-4)(x-33)=0\Rightarrow x=4\) 或 \(x=33\)（不合），售價為 \(200-5\times4=180\)（元）。')
ch(r'【素養】如附圖，在一塊正方形土地的兩角分別圍出同樣大小的小正方形。若剩餘（上色）的土地面積為 137 平方公尺，已知 \(\overline{AB}=5\) 公尺，則剩餘土地的周長為多少公尺？',['48','52','56','60'],2,r'設小正方形邊長為 \(x\) 公尺，大正方形邊長為 \((2x+5)\) 公尺，\((2x+5)^2-2x^2=137\Rightarrow2x^2+20x-112=0\Rightarrow x^2+10x-56=0\Rightarrow(x-4)(x+14)=0\Rightarrow x=4\) 或 \(x=-14\)（不合），周長＝\(4(2\times4+5)=52\)（公尺）。',img=(25,912,1255,1003,1368))
ch('【素養】柳橙園中有 24 棵柳橙樹，每棵平均可生產柳橙 400 個。若柳橙園中，每加種 1 棵，每棵平均產量減少 10 個，則果農需加種多少棵，才能收成 10240 個柳橙？',['8','9','10','12'],1,r'設加種 \(x\) 棵，\((400-10x)(24+x)=10240\Rightarrow9600+160x-10x^2=10240\Rightarrow x^2-16x+64=0\Rightarrow(x-8)^2=0\Rightarrow x=8\)（重根）。')
ch(r'【素養】如附圖，正方形 \(ABCD\) 的邊長為 \(x\)，\(\overline{EC}=1\)，且 \(\triangle ABE\) 與正方形 \(ABCD\) 的面積比為 1：3，則正方形 \(ABCD\) 的邊長為何？',['3','4','5','6'],1,r'直角 \(\triangle ABE\) 中，\(\overline{AB}=x\)，\(\overline{BE}=x-1\)，\(\dfrac{1}{2}x(x-1):x^2=1:3\Rightarrow\dfrac{3}{2}x^2-\dfrac{3}{2}x=x^2\Rightarrow3x^2-3x=2x^2\Rightarrow x^2-3x=0\Rightarrow x(x-3)=0\Rightarrow x=0\)（不合）或 3。',img=(26,388,218,508,332))
endp()

sec('第14回 第5章 統計資料處理')
psg('附表是小美班上同學體重相對次數分配表：45～50 公斤 2 人；50～55 公斤 5 人；55～60 公斤 8 人；60～65 公斤 7 人；65～70 公斤 3 人。')
ch('該班同學體重在 50～55 公斤的學生人數占全班學生人數的百分比為何？',['15%','17.5%','20%','25%'],3,r'全班 \(2+5+8+7+3=25\)（人），\(\dfrac{5}{25}\times100\%=20\%\)。',img=(27,75,400,490,498))
ch('繪製該班同學體重相對次數分配折線圖時，60～65 公斤對應的點坐標為何？',['(60, 28)','(62.5, 28)','(62.5, 18)','(65, 28)'],2,r'\(\dfrac{7}{25}\times100\%=28\%\)，60～65 公斤標示在 (62.5, 28)。',img=(27,75,400,490,498))
psg('附圖是小延班上同學身高的累積次數分配折線圖。')
ch('請問小延班上同學人數為多少人？',['32','28','24','20'],4,r'由圖可知全班有 20 人。',img=(27,135,868,380,1068))
ch('學校規定學生身高在 160 公分以上（含）才能參加籃球社，請問小延班上有多少人符合參加資格？',['18','15','14','12'],2,r'\(20-5=15\)（人）。',img=(27,135,868,380,1068))
psg('附表是甲班數學段考的累積次數分配表：50～60 分 3 人；60～70 分 10 人；70～80 分 18 人；80～90 分 23 人；90～100 分 25 人（皆為累積次數）。')
ch('【素養】繪製該班數學段考的累積次數分配折線圖時，60～70 分所對應的點坐標為何？',['(60, 10)','(65, 10)','(70, 10)','(70, 7)'],3,r'60～70 分對應的點坐標為 (70, 10)。',img=(27,80,1400,512,1462))
ch('【素養】成績在 70～80 分的人數占全班人數的百分比為何？',['8%','16%','24%','32%'],4,r'70～80 分有 \(18-10=8\)（人），\(\dfrac{8}{25}\times100\%=32\%\)。',img=(27,80,1400,512,1462))
psg('附圖為翰翰班上某次段考自然科成績的相對次數分配折線圖。若翰翰班上學生總數為 40 人。')
ch('【素養】請問成績在哪一組的人數最多？',['50～60 分','60～70 分','70～80 分','80～90 分'],3,r'70～80 分占 25% 最多，所以人數最多。',img=(27,782,543,1002,660))
ch('【素養】成績未滿 60 分的學生共有多少人？',['10','15','20','25'],1,r'\(40\times(5\%+10\%+10\%)=10\)（人）。',img=(27,782,543,1002,660))
psg('附圖為翰林國中八年級學生某次數學競試成績的累積相對次數分配折線圖，若八年級學生人數為 600 人。')
ch('【素養】成績 50～70 分的人數占全部人數的百分比為何？',['25%','30%','35%','45%'],2,r'50～70 分占 \(45\%-15\%=30\%\)。',img=(27,765,1055,1005,1222))
ch('【素養】此次競試成績在 80 分以上（含）的共有多少人？',['180','240','300','420'],1,r'\(100\%-70\%=30\%\)，\(600\times30\%=180\)（人）。',img=(27,765,1055,1005,1222))
psg('附圖是大豐國中健康中心統計男、女學生 BMI 所繪製的累積相對次數分配折線圖。【素養題】')
ch('【素養】男、女 BMI 值未達 24 的百分比相差多少？',['20%','15%','10%','5%'],3,r'男：40%，女：50%，相差 \(50\%-40\%=10\%\)。',img=(28,285,55,512,202))
ch('【素養】男、女 BMI 值在 22～28 的百分比相差多少？',['60%','55%','10%','5%'],4,r'男：\(75\%-20\%=55\%\)；女：\(90\%-30\%=60\%\)，相差 \(60\%-55\%=5\%\)。',img=(28,285,55,512,202))
endp()

sec('第15回 4-1～第5章 複習')
ch('下列何者為一元二次方程式？',[r'\((x+1)^2=x^2-1\)',r'\(2x^3+x=2\)',r'\(2x^2-4x+3\)',r'\(3-2x=5x^2\)'],4,r'(A) \(x^2+2x+1=x^2-1\Rightarrow2x+2=0\)（一元一次方程式）；(B) 一元三次方程式；(C) 一元二次式。')
ch(r'若 \(x^2-8x+\square\) 為完全平方式，則 \(\square=\)？',['16','－16','8','－8'],1,r'\(\square=\left(\dfrac{8}{2}\right)^2=16\)。')
ch(r'若 \(a\)、\(b\) 為方程式 \((x+3)(x-7)=0\) 的兩個解，且 \(a>b\)，則 \(2a-b\) 之值為何？',['17','15','13','11'],1,r'方程式的解為 －3 與 7，故 \(a=7\)，\(b=-3\)，\(2a-b=2\times7-(-3)=17\)。')
ch(r'利用公式解，求 \(2x^2-5x+3=0\) 的解，則正確結果是下列哪一個？',[r'\(x=\dfrac{-2\pm\sqrt{(-5)^2-4\times2\times3}}{2\times3}\)',r'\(x=\dfrac{-3\pm\sqrt{(-5)^2-4\times2\times3}}{2\times2}\)',r'\(x=\dfrac{5\pm\sqrt{(-5)^2-4\times2\times3}}{2\times2}\)',r'\(x=\dfrac{5\pm\sqrt{(-5)^2-4\times2\times3}}{2\times3}\)'],3,r'\(a=2\)，\(b=-5\)，\(c=3\)，\(x=\dfrac{-b\pm\sqrt{b^2-4ac}}{2a}=\dfrac{5\pm\sqrt{(-5)^2-4\times2\times3}}{2\times2}\)。')
ch(r'【素養】若 \(x^2-16x+\square\) 可以配成一個完全平方式 \((x+\triangle)^2\)，則 \(\square\) 和 \(\triangle\) 的值分別為何？',[r'\(\square=16\)，\(\triangle=-8\)',r'\(\square=16\)，\(\triangle=8\)',r'\(\square=64\)，\(\triangle=-8\)',r'\(\square=64\)，\(\triangle=8\)'],3,r'\(x^2-16x+64=(x-8)^2\)，故 \(\square=64\)，\(\triangle=-8\)。')
ch(r'【素養】若 \(x=-3\) 為一元二次方程式 \(2x^2-ax-21=0\) 的一個解，則此方程式的另一個解為何？',['1','3',r'\(\dfrac{3}{2}\)',r'\(\dfrac{7}{2}\)'],4,r'\(x=-3\) 代入得 \(18+3a-21=0\Rightarrow a=1\)，\(2x^2-x-21=0\Rightarrow(x+3)(2x-7)=0\Rightarrow x=-3\) 或 \(x=\dfrac{7}{2}\)。')
ch(r'【素養】判別一元二次方程式 \(x^2-3x-a=0\) 中的 \(a\) 為下列哪一個數時，可使此方程式的兩根皆為整數？',['12','14','16','18'],4,r'取 \(a=18\)，\(x^2-3x-18=0\Rightarrow(x+3)(x-6)=0\Rightarrow x=-3\) 或 \(x=6\)。')
ch('【素養】有兩個連續正奇數，其平方和為 650，則兩正奇數的和為何？',['34','35','36','37'],3,r'設兩奇數為 \(x\)、\(x+2\)，\(x^2+(x+2)^2=650\Rightarrow2x^2+4x=646\Rightarrow x^2+2x=323\Rightarrow(x+1)^2=324\Rightarrow x+1=\pm18\Rightarrow x=17\) 或 \(x=-19\)（不合），兩正奇數的和為 \(17+19=36\)。')
ch(r'【素養】如附圖，用 1 個長方形 \(EFCD\) 和 4 個相同大小的正方形，可以拼成長方形 \(ABCD\)，其長度滿足 \(\dfrac{\overline{AD}}{\overline{CD}}=\dfrac{\overline{CD}}{\overline{DE}}\)。若 \(\overline{DE}=4\)，小正方形的邊長為 \(x\)，則 \(x=\)？',[r'\(-1+\sqrt{5}\)',r'\(1+\sqrt{5}\)',r'\(\dfrac{-1+\sqrt{5}}{2}\)',r'\(\dfrac{1+\sqrt{5}}{2}\)'],2,r'\(\dfrac{2x+4}{2x}=\dfrac{2x}{4}\Rightarrow x^2-2x-4=0\Rightarrow x=\dfrac{2\pm\sqrt{20}}{2}=1\pm\sqrt{5}\)（負不合），故 \(x=1+\sqrt{5}\)。',img=(29,885,785,1002,868))
ch(r'【素養】愛美是天性，女生喜歡穿高跟鞋也是有科學根據的。如果「全身高度：下半身長＝下半身長：上半身長」，則被稱為人體黃金比例。已知今天小凡身高 140 公分，下半身長為 80 公分，若她想利用穿上 \(x\) 公分的高跟鞋，讓自己看起來擁有黃金比例，則利用公式解可求得 \(x=\)？',[r'\(-30+30\sqrt{5}\)',r'\(-40+30\sqrt{5}\)',r'\(-50+30\sqrt{5}\)',r'\(-60+30\sqrt{5}\)'],3,r'小凡穿上高跟鞋後全身高度為 \((x+140)\) 公分，上半身長為 60 公分，下半身長為 \((x+80)\) 公分，\((x+140):(x+80)=(x+80):60\Rightarrow(x+80)^2=60(x+140)\Rightarrow x^2+100x-2000=0\Rightarrow x=\dfrac{-100\pm\sqrt{18000}}{2}=\dfrac{-100\pm60\sqrt{5}}{2}=-50\pm30\sqrt{5}\)（負不合），故 \(x=-50+30\sqrt{5}\)。')
psg('附圖為某校第三次段考數學成績的累積相對次數分配折線圖，若全校學生總數為 900 人。')
ch('【素養】成績 70～90 分的學生占全校學生總數的百分比為何？',['32%','40%','52%','72%'],3,r'\(92\%-40\%=52\%\)。',img=(30,315,52,512,222))
ch('【素養】成績在 80 分以上的學生有多少人？',['252','256','272','280'],1,r'\(900\times(100\%-72\%)=900\times28\%=252\)（人）。',img=(30,315,52,512,222))
endp()
